import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadMont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// EXU TIRIRI 2026 (cliente elias garcia): adoração no dia 28/11 às 18h, elementos de adoração e presentes, endereço.
// Identidade do cartaz do cliente: preto, fumaça azul, letra serifada de metal dourado/prata com fogo; o vermelho e preto
// da imagem do Exu com o bode. Pouco material (cartaz + imagem) → motion. Voz o locutor (src/voz-v1-curta.wav), entra em 0,2 s;
// os tempos abaixo são da voz (t = tempo do vídeo − 0,2).

const { fontFamily: CZ } = loadCinzel("normal", { weights: ["600", "700", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: MT } = loadMont("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });

export const EG_FPS = 30;
const OFF = 0.2;
export const EG_FRAMES = Math.round(41.7 * EG_FPS);

const BG = "#050608";
const GOLD = "#F2B24A";
const SILVER = "#E9E6DF";
const SUB = "#8F9AA8";
const BLUE = "#2A8FD8";
const RED = "#C8102E";
const METAL_GOLD = "linear-gradient(180deg, #FFF4D8 0%, #F6C66A 45%, #D98A2E 75%, #9C561B 100%)";
const METAL_SILVER = "linear-gradient(180deg, #FFFFFF 0%, #E6E3DC 55%, #9C9EA4 100%)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN = Easing.in(Easing.cubic);
const BACK = Easing.out(Easing.back(1.25));
const k = (t: number, a: number, d = 0.45, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const kin = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const fit = (s: string, size: number, max = 840) => Math.min(size, max / (s.length * 0.8));

// ───────── texto: sobe da linha por máscara e fica parado; sai descendo pela máscara ─────────
const Ln: React.FC<{ t: number; a: number; b?: number; size: number; metal?: string; color?: string; w?: number; ls?: string; glow?: boolean; children: string }> = ({ t, a, b = 999, size, metal, color = SILVER, w = 700, ls = "0.02em", glow, children }) => {
  const e = k(t, a, 0.5);
  const p = k(t, a, 0.55, BACK);
  const o = kin(t, b, 0.25);
  if (t < a || o >= 1) return null;
  return (
    <div style={{ overflow: "hidden", padding: `${size * 0.22}px ${size * 0.15}px ${size * 0.06}px`, margin: `${-size * 0.22}px ${-size * 0.15}px ${-size * 0.06}px` }}>
      <div style={{
        fontFamily: CZ, fontWeight: w, fontSize: size, lineHeight: 1.04, letterSpacing: ls, whiteSpace: "nowrap", textAlign: "center",
        ...(metal ? { backgroundImage: metal, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", paddingTop: "0.22em", marginTop: "-0.22em" } : { color }),
        filter: glow ? "drop-shadow(0 0 22px rgba(242,178,74,0.35))" : undefined,
        transform: `translateY(${((1 - e) * 110 + o * 110).toFixed(2)}%) scale(${(1.12 - 0.12 * p).toFixed(4)})`,
      }}>{children}</div>
    </div>
  );
};

// rótulo pequeno: traço dourado + caixa alta espaçada
const Label: React.FC<{ t: number; a: number; b?: number; color?: string; size?: number; children: string }> = ({ t, a, b = 999, color = GOLD, size = 40, children }) => {
  const e = k(t, a, 0.45) * (1 - kin(t, b, 0.25));
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 22, opacity: e, fontFamily: MT, fontWeight: 700, fontSize: size, letterSpacing: "0.32em", color, whiteSpace: "nowrap" }}>
      <span style={{ width: 70 * e, height: 3, background: color }} />
      <span style={{ marginRight: "-0.32em" }}>{children}</span>
      <span style={{ width: 70 * e, height: 3, background: color }} />
    </div>
  );
};

const Col: React.FC<{ top: number; gap?: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ top, gap = 0, style, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);

// fundo liso preto com uma luz azul (a fumaça do cartaz) muito suave, deslocando devagar
const Fundo: React.FC<{ t: number; tint?: string; y?: number }> = ({ t, tint = "rgba(42,143,216,0.16)", y = 82 }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 45% at ${(50 + Math.sin(t * 0.7) * 18).toFixed(1)}% ${y}%, ${tint} 0%, rgba(5,6,8,0) 70%)` }} />
  </AbsoluteFill>
);

// ───────── ícones em traço dourado (desenham-se) ─────────
const S = (c: string = GOLD, w = 9) => ({ fill: "none", stroke: c, strokeWidth: w, strokeLinecap: "round" as const, strokeLinejoin: "round" as const });
const draw = (e: number) => ({ pathLength: 1, strokeDasharray: 1, strokeDashoffset: 1 - e });

const Icone: React.FC<{ n: number; e: number; size: number; c?: string; w?: number }> = ({ n, e, size, c = GOLD, w = 9 }) => {
  const s = S(c, w);
  const d = draw(e);
  const flame = (cx: number, cy: number, sc = 1) => (
    <path d={`M${cx} ${cy} c${-14 * sc} ${-16 * sc} ${-12 * sc} ${-34 * sc} 0 ${-50 * sc} c${12 * sc} ${16 * sc} ${14 * sc} ${34 * sc} 0 ${50 * sc} z`} fill={c} opacity={e} />
  );
  const parts: React.ReactNode[][] = [
    // velas
    [<rect key="a" x={62} y={110} width={52} height={150} rx={6} {...s} {...d} />, <rect key="b" x={128} y={140} width={52} height={120} rx={6} {...s} {...d} />,
      <path key="c" d="M88 110 V92 M154 140 V122" {...s} {...d} />, <g key="f">{flame(88, 86, 0.9)}{flame(154, 116, 0.75)}</g>, <path key="g" d="M40 262 H200" {...s} {...d} />],
    // charuto
    [<rect key="a" x={30} y={140} width={170} height={44} rx={22} {...s} {...d} />, <path key="b" d="M160 140 V184 M172 140 V184" {...s} {...d} />,
      <path key="c" d="M214 132 c14 -18 -10 -30 4 -50 c12 -16 -6 -28 4 -44" {...S(c, 6)} {...draw(Math.max(0, e * 1.4 - 0.4))} opacity={0.75} />],
    // bebidas: garrafa + taça
    [<path key="a" d="M70 50 H96 V92 C120 104 126 124 126 146 V262 H40 V146 C40 124 46 104 70 92 Z" {...s} {...d} />, <path key="b" d="M40 180 H126" {...s} {...d} />,
      <path key="c" d="M150 120 H214 C214 168 198 186 182 188 C166 186 150 168 150 120 Z M182 188 V250 M156 256 H208" {...s} {...d} />],
    // flores
    [<path key="a" d="M120 262 V140 M120 210 C96 206 82 190 80 170 C104 172 118 186 120 210 M120 196 C144 192 158 176 160 156 C136 158 122 172 120 196" {...s} {...d} />,
      ...[0, 72, 144, 216, 288].map((r) => <ellipse key={r} cx={120} cy={70} rx={18} ry={36} {...s} {...d} style={{ transform: `rotate(${r}deg) translateY(-26px)`, transformOrigin: "120px 96px" }} />),
      <circle key="m" cx={120} cy={96} r={12} fill={c} opacity={e} />],
    // nota de dinheiro
    [<rect key="a" x={20} y={84} width={200} height={110} rx={10} {...s} {...d} />, <circle key="b" cx={120} cy={139} r={28} {...s} {...d} />,
      <path key="c" d="M50 112 V166 M190 112 V166" {...s} {...d} />, <path key="d" d="M36 214 H204" {...S(c, 6)} {...d} opacity={0.6} />],
  ];
  return (
    <svg viewBox="0 0 240 280" width={size} height={(size * 280) / 240} style={{ overflow: "visible" }}>
      {parts[n]}
    </svg>
  );
};

const Pin: React.FC<{ e: number; size: number }> = ({ e, size }) => (
  <svg viewBox="0 0 200 260" width={size} height={(size * 260) / 200} style={{ overflow: "visible" }}>
    <path d="M100 246 C100 246 22 156 22 98 C22 52 57 18 100 18 C143 18 178 52 178 98 C178 156 100 246 100 246 Z" {...S(GOLD, 12)} {...draw(e)} />
    <circle cx={100} cy={98} r={30} fill={GOLD} opacity={e} />
  </svg>
);

const Coracao: React.FC<{ size: number; c?: string }> = ({ size, c = GOLD }) => (
  <svg viewBox="0 0 100 90" width={size} height={size * 0.9}>
    <path d="M50 84 C20 62 6 46 6 28 C6 14 17 6 29 6 C39 6 46 12 50 20 C54 12 61 6 71 6 C83 6 94 14 94 28 C94 46 80 62 50 84 Z" fill={c} />
  </svg>
);
const Tecido: React.FC<{ size: number }> = ({ size }) => (
  <svg viewBox="0 0 100 80" width={size} height={size * 0.8}>
    {[RED, GOLD, BLUE].map((c, i) => <path key={c} d={`M8 ${18 + i * 22} C28 ${8 + i * 22} 44 ${28 + i * 22} 60 ${18 + i * 22} S88 ${10 + i * 22} 94 ${18 + i * 22}`} fill="none" stroke={c} strokeWidth={12} strokeLinecap="round" />)}
  </svg>
);

// ───────── cenas (tempos da voz) ─────────
const T1 = 3.75, T2 = 7.6, T3 = 19.45, T4 = 20.9, T5 = 29.95, T6 = 35.4;

// 1 · o cartaz do cliente: começa colado na figura de cartola e abre revelando EXU TIRIRI 2026; mergulha no 2026
const Cena1: React.FC<{ t: number }> = ({ t }) => {
  const open = k(t, -0.1, 1.35, Easing.bezier(0.45, 0, 0.2, 1));
  const dive = kin(t, T1 - 0.32, 0.32);
  const sc = 1.8 - 0.8 * open + 0.05 * k(t, 0.9, 2.5, Easing.linear) + dive * 2.2;
  const fy = interpolate(open, [0, 1], [640, 0]) - dive * 300; // desloca para a figura no começo, para o 2026 no mergulho
  const beat = (a: number) => Math.exp(-Math.max(0, t - a) * 9) * (t >= a ? 1 : 0);
  const bright = 1 + 0.18 * beat(0.94) + 0.22 * beat(2.02);
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `translateY(${fy.toFixed(1)}px) scale(${sc.toFixed(4)})`, transformOrigin: "50% 62%", filter: `brightness(${bright.toFixed(3)}) blur(${(dive * 14).toFixed(1)}px)`, opacity: 1 - dive }}>
        <Img src={staticFile("elias/cartaz.jpg")} style={{ position: "absolute", left: -210, top: 29, width: 1500, height: 2198 }} />
        {/* o fim do cartaz (horário e o outro endereço) fica coberto: o endereço deste vídeo é o que veio na mensagem */}
        <div style={{ position: "absolute", left: -200, right: -200, top: 1640, height: 600, background: `linear-gradient(180deg, rgba(5,6,8,0) 0%, ${BG} 30%)` }} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// 2 · a data: 28 grande em metal dourado; entra já em movimento e fecha numa linha dourada
const Cena2: React.FC<{ t: number }> = ({ t }) => {
  const enter = k(t, T1, 0.6);
  const sc = 1.25 - 0.25 * enter + 0.04 * k(t, T1 + 0.6, 3, Easing.linear);
  const close = k(t, T2 - 0.38, 0.32, IN);
  const line = k(t, T2 - 0.5, 0.25);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Fundo t={t} y={70} />
      <AbsoluteFill style={{ transform: `scale(${sc.toFixed(4)}) scaleY(${(1 - close).toFixed(4)})`, opacity: 1 - close * 0.6 }}>
        <Col top={560} gap={8}>
          <Label t={t} a={T1 + 0.1}>DIA</Label>
          <Ln t={t} a={4.5} size={430} metal={METAL_GOLD} w={900} glow>28</Ln>
          <Ln t={t} a={4.9} size={104} metal={METAL_SILVER}>DE NOVEMBRO</Ln>
        </Col>
        <Col top={1400}>
          <div style={{ display: "flex", alignItems: "center", gap: 26, padding: "22px 54px 20px", border: `4px solid ${GOLD}`, borderRadius: 999, opacity: k(t, 6.15, 0.3), transform: `scaleX(${(0.6 + 0.4 * k(t, 6.15, 0.45, BACK)).toFixed(4)})` }}>
            <svg viewBox="0 0 60 60" width={64} height={64}><circle cx={30} cy={30} r={25} {...S(GOLD, 5)} /><path d="M30 16 V30 L40 37" {...S(GOLD, 5)} /></svg>
            <Ln t={t} a={6.25} size={78} color={SILVER}>ÀS 18 HORAS</Ln>
          </div>
        </Col>
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 540 - 470 * line, width: 940 * line, top: 1040, height: 4, background: GOLD, opacity: line * (1 - k(t, T2 - 0.05, 0.1)), boxShadow: "0 0 18px rgba(242,178,74,0.6)" }} />
    </AbsoluteFill>
  );
};

// 3 e 4 · a imagem do Exu nasce da linha dourada; o título sobe e vira o cabeçalho da lista dos elementos
const ITENS: { a: number; b: React.ReactNode; l1: string; l2?: string }[] = [
  { a: 9.6, b: "1", l1: "BODE ADULTO" },
  { a: 11.1, b: "7", l1: "GALOS" },
  { a: 12.72, b: "coracao", l1: "CORAÇÃO DE BOI" },
  { a: 14.1, b: "7", l1: "PEDAÇOS DE", l2: "COSTELA DE BOI" },
  { a: 16.44, b: "1", l1: "BALAIO GRANDE" },
  { a: 17.94, b: "tecido", l1: "TECIDOS", l2: "COLORIDOS" },
];
const Cena34: React.FC<{ t: number }> = ({ t }) => {
  const open = k(t, T2, 0.5);
  const up = k(t, 9.0, 0.5);
  const leave = (i: number) => kin(t, T3 - 0.42 + i * 0.04, 0.3);
  const statue = 1 - kin(t, 8.85, 0.3);
  const sy = interpolate(k(t, T2, 1.4), [0, 1], [120, 0]) - kin(t, 8.85, 0.3) * 380;
  const tTop = interpolate(up, [0, 1], [1400, 236]);
  const tSc = interpolate(up, [0, 1], [1, 0.74]);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Fundo t={t} tint="rgba(232,118,43,0.12)" y={55} />
      <AbsoluteFill style={{ clipPath: `inset(${(50 - 50 * open).toFixed(2)}% 0 ${(50 - 50 * open).toFixed(2)}% 0)` }}>
        <Fundo t={t} tint="rgba(232,118,43,0.12)" y={55} />
        {statue > 0 && (
          <div style={{ position: "absolute", left: 0, right: 0, top: 290, display: "flex", justifyContent: "center", opacity: statue, transform: `translateY(${sy.toFixed(1)}px) scale(${(1.08 - 0.08 * k(t, T2, 1.4)).toFixed(4)})`, filter: `blur(${((1 - statue) * 10).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", top: 420, width: 820, height: 560, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(242,150,60,0.28), rgba(5,6,8,0))" }} />
            <Img src={staticFile("elias/exu.png")} style={{ width: 830, height: (830 * 699) / 553, position: "relative" }} />
          </div>
        )}
        <div style={{ position: "absolute", left: 0, right: 0, top: tTop, display: "flex", flexDirection: "column", alignItems: "center", transform: `scale(${(tSc * (1 + 0.03 * k(t, 9.4, 10, Easing.linear))).toFixed(4)})`, transformOrigin: "50% 0%", opacity: 1 - leave(0) }}>
          {/* fundo escuro atrás do título enquanto ele está sobre a imagem */}
          <Ln t={t} a={7.75} size={70} color={SILVER} ls="0.12em">OS ELEMENTOS</Ln>
          <Ln t={t} a={8.45} size={112} metal={METAL_GOLD} w={900} glow>DE ADORAÇÃO</Ln>
        </div>
        <div style={{ position: "absolute", left: 120, right: 120, top: 560, display: "flex", justifyContent: "center", transform: `scale(${(1 + 0.05 * k(t, 9.4, 10, Easing.linear)).toFixed(4)})`, transformOrigin: "50% 0%" }}><div style={{ width: 800, display: "flex", flexDirection: "column", gap: 46 }}>
          {ITENS.map((it, i) => {
            if (t < it.a - 0.05) return <div key={i} style={{ height: it.l2 ? 160 : 120 }} />;
            const e = k(t, it.a - 0.05, 0.5);
            const pop = k(t, it.a - 0.05, 0.5, BACK);
            const next = ITENS[i + 1]?.a ?? 99;
            const on = t < next - 0.05;
            const lv = leave(i + 1);
            return (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 40, height: it.l2 ? 160 : 120, opacity: (on ? 1 : 0.62) * (1 - lv), transform: `translateX(${((1 - e) * -60 - lv * 300).toFixed(1)}px)`, filter: `blur(${(lv * 8).toFixed(1)}px)` }}>
                <div style={{ width: 120, height: 120, flex: "none", borderRadius: "50%", border: `4px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop.toFixed(4)})`, background: on ? "rgba(242,178,74,0.14)" : "transparent", boxShadow: on ? "0 0 26px rgba(242,178,74,0.35)" : "none" }}>
                  {it.b === "coracao" ? <Coracao size={60} /> : it.b === "tecido" ? <Tecido size={74} /> : <div style={{ fontFamily: CZ, fontWeight: 900, fontSize: 72, color: GOLD, marginTop: -6 }}>{it.b}</div>}
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start" }}>
                  <Ln t={t} a={it.a + 0.04} size={66} color={on ? "#FFFFFF" : SILVER}>{it.l1}</Ln>
                  {it.l2 && <Ln t={t} a={it.a + 0.16} size={66} color={on ? "#FFFFFF" : SILVER}>{it.l2}</Ln>}
                </div>
              </div>
            );
          })}
        </div></div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// 5 · "E os presentes": a palavra entra, um ponto dourado nasce embaixo e inunda a tela na cena seguinte
const Cena5: React.FC<{ t: number }> = ({ t }) => {
  const dot = k(t, 20.3, 0.3, BACK);
  const flood = k(t, T4 - 0.32, 0.5, Easing.in(Easing.quad));
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Fundo t={t} y={50} />
      <Col top={760} gap={14}>
        <Ln t={t} a={19.62} size={80} color={SILVER} ls="0.14em">E OS</Ln>
        <Ln t={t} a={19.86} size={128} metal={METAL_GOLD} w={900} glow>PRESENTES</Ln>
      </Col>
      <div style={{ position: "absolute", left: 540, top: 1170, width: 0, height: 0 }}>
        <div style={{ position: "absolute", width: 36, height: 36, left: -18, top: -18, borderRadius: "50%", background: GOLD, transform: `scale(${dot.toFixed(4)})` }} />
      </div>
      <AbsoluteFill style={{ background: "#0A1520", clipPath: `circle(${(flood * 2300).toFixed(1)}px at 540px 1170px)` }} />
    </AbsoluteFill>
  );
};

// 6 · os presentes, um por vez e grande, no mesmo lugar; a fileira de baixo acende um a um
const PRES: { a: number; l: string; s?: string }[] = [
  { a: 20.98, l: "VELAS", s: "COLORIDAS" },
  { a: 22.5, l: "CHARUTO" },
  { a: 23.78, l: "BEBIDAS", s: "DESTILADAS · FERMENTADAS · VINHO" },
  { a: 27.02, l: "FLORES", s: "NATURAIS" },
  { a: 28.67, l: "NOTA DE", s: "DINHEIRO" },
];
const Cena6: React.FC<{ t: number }> = ({ t }) => {
  const cur = PRES.reduce((acc, p, i) => (t >= p.a - 0.12 ? i : acc), 0);
  const p = PRES[cur];
  const nextA = PRES[cur + 1]?.a ?? T5 + 0.3;
  const out = kin(t, nextA - 0.3, 0.2);
  const push = kin(t, T5 - 0.3, 0.3);
  const e = k(t, p.a - 0.12, 0.6);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: "#0A1520" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse 80% 40% at 50% 46%, rgba(42,143,216,0.18), rgba(10,21,32,0) 70%)" }} />
      <AbsoluteFill style={{ transform: `translateY(${(-push * 520).toFixed(1)}px) scale(${(1.04 - 0.04 * k(t, T4, 9, Easing.linear)).toFixed(4)})`, filter: `blur(${(push * 16).toFixed(1)}px)`, opacity: 1 - push }}>
        <Col top={290}><Label t={t} a={T4 - 0.05} size={38}>PRESENTES</Label></Col>
        <div style={{ position: "absolute", left: 0, right: 0, top: 470, display: "flex", justifyContent: "center", opacity: 1 - out, transform: `scale(${(0.82 + 0.18 * k(t, p.a - 0.12, 0.55, BACK) - out * 0.1).toFixed(4)}) rotate(${((1 - e) * -6).toFixed(2)}deg)` }}>
          <div style={{ position: "absolute", top: 120, width: 520, height: 360, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(242,178,74,0.16), rgba(10,21,32,0))" }} />
          <Icone n={cur} e={e} size={380} />
        </div>
        <Col top={990} gap={10} style={{ opacity: 1 - out }}>
          <Ln key={`l${cur}`} t={t} a={p.a} size={fit(p.l, 120)} metal={METAL_GOLD} w={900}>{p.l}</Ln>
          {p.s && (p.s.length > 16
            ? <div style={{ opacity: k(t, p.a + 0.25, 0.4), fontFamily: MT, fontWeight: 700, fontSize: 34, letterSpacing: "0.12em", color: SILVER, whiteSpace: "nowrap", marginTop: 12 }}>
                {p.s.split(" · ").map((w, i) => <span key={w} style={{ opacity: k(t, [23.95, 25.3, 26.15][i] ?? 0, 0.3) }}>{i ? <span style={{ color: GOLD }}>{"  ·  "}</span> : null}{w}</span>)}
              </div>
            : <Ln key={`s${cur}`} t={t} a={p.a + 0.3} size={78} metal={METAL_SILVER}>{p.s}</Ln>)}
        </Col>
        <div style={{ position: "absolute", left: 120, right: 120, top: 1440, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {PRES.map((q, i) => {
            const shown = k(t, T4 + i * 0.08, 0.4);
            const lit = t >= q.a - 0.12;
            return (
