export const ExuTiriri: React.FC<{ som?: boolean }> = ({ som = true }) => {
  const frame = useCurrentFrame();
  const t = frame / EG_FPS - OFF;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {t < T1 ? <Cena1 t={t} />
        : t < T2 ? <Cena2 t={t} />
        : t < T3 ? <Cena34 t={t} />
        : t < T4 ? <Cena5 t={t} />
